import {
  AngleSliderRoot,
  AngleSliderTrack,
  AngleSliderThumb,
  AngleSliderValueText,
  AngleSliderHiddenInput,
} from '@uifn/components-react/angle-slider'
import '@uifn/components/styles.css'

export function Example() {
  return (
    <AngleSliderRoot defaultValue={225} min={0} max={360} step={1} name="rotation">
      <AngleSliderTrack />
      <AngleSliderThumb />
      <AngleSliderValueText>225°</AngleSliderValueText>
      <AngleSliderHiddenInput />
    </AngleSliderRoot>
  )
}

import {
  CheckboxRoot,
  CheckboxControl,
  CheckboxIndicator,
  CheckboxLabel,
  CheckboxHiddenInput,
} from '@uifn/components-react/checkbox'
import '@uifn/components/styles.css'

export function Example() {
  return (
    <CheckboxRoot defaultChecked name="notifications">
      <CheckboxControl type="button">
        <CheckboxIndicator>✓</CheckboxIndicator>
      </CheckboxControl>
      <CheckboxLabel>Email notifications</CheckboxLabel>
      <CheckboxHiddenInput />
    </CheckboxRoot>
  )
}

